        self.fieldnames: Collection[str] = list(rows[0].keys()) if (
            not self._header_written
            and self.fieldnames is None
            and (rows := [record.to_dict() if isinstance(record, Record) else record for record in self._buffer])
        ) else (self.fieldnames or [])
        self._header_written = False

    def flush(self) -> None:
        if not self._buffer:
